    max-width: 500px;
    padding: 0.75rem;
    border: 2px solid #ddd;
    border-radius: 4px;
    font-family: inherit;
    font-size: 1rem;
    transition: border-color 0.2s, box-shadow 0.2s, outline 0.2s, outline-offset 0.2s;
    background-color: white;
}

input.old_string:
label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--text-color);
}

label span {
    font-size: 0.875rem;
    opacity: 0.75;
}

input.new_string:
label {
    display: block;
    margin-bottom: 0.5rem;
    font-weight: 600;
    color: var(--text-color);
    font-size: 0.95rem;
}

label span {
    display: inline;
    font-size: 0.875rem;
    font-weight: 400;
    opacity: 0.75;
    margin-left: 0.25rem;
}

